        "EstoqueMaximo" integer NOT NULL,
        "NCM" integer NOT NULL,
        "CEST" integer NOT NULL,
        "OrigemMercadoria" text NOT NULL,
        "Ativo" boolean NOT NULL,
        CONSTRAINT "PK_CadastroItens" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

